const evt=$input.first().json?.raw_data||$input.first().json;
const username=evt.username||evt.user||evt.email;
const src_ip=evt.src_ip||evt.ip||'0.0.0.0';
const login_time=new Date(evt.timestamp||Date.now());
return[{json:{username,src_ip,login_time:login_time.toISOString(),
  country:evt.geo_country||evt.country||'Unknown',
  city:evt.geo_city||evt.city||'Unknown',
  event_id:`IAM-LOGIN-${Date.now()}`}}];

const current=$('Check Impossible Travel').first().json;
const prev_logins=$('Get Previous Login').all().map(i=>i.json);
if(prev_logins.length===0){
  return[{json:{...current,is_impossible:false,velocity_kmh:0,prev_country:null,
    reason:'No previous login in 2hr window'}}];
}
const prev=prev_logins[0];
const time_diff_hours=(new Date(current.login_time)-new Date(prev.login_time))/3600000;
const country_changed=prev.country&&prev.country!==current.country&&prev.country!=='Unknown';
// Rough max travel: commercial flight ~900 km/h — if different country in < 2hr = impossible
const is_impossible=country_changed&&time_diff_hours<2;
const confidence=is_impossible?88:40;
return[{json:{...current,is_impossible,prev_country:prev.country,prev_ip:prev.src_ip,
  time_diff_hours:time_diff_hours.toFixed(2),confidence,
  reason:is_impossible?`Login from ${current.country} then ${prev.country} in ${time_diff_hours.toFixed(1)}hr — impossible travel`:'No anomaly detected'}}];
